"use client";

import * as React from "react";
import {
  type Column,
  type ColumnFiltersState,
  type SortingState,
  type Table as TanstackTable,
  flexRender,
  getCoreRowModel,
  getFacetedMinMaxValues,
  getFacetedRowModel,
  getFacetedUniqueValues,
  getFilteredRowModel,
  getPaginationRowModel,
  getSortedRowModel,
  useReactTable,
} from "@tanstack/react-table";
import { ArrowDown, ArrowUp, ChevronsUpDown, X } from "lucide-react";

import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Slider } from "@/components/ui/slider";
import { cn } from "@/lib/utils";

import { filterDescriptors, searchableIds, toColumnDefs, type ColumnMeta } from "./builder";
import type { ColumnAlign, ColumnDescriptor, TableSchema } from "./types";
import { SkeletonRows, TableEmptyState } from "./table-primitives";

/** Map a schema `align` to the matching text-alignment utility. */
function alignClass(align: ColumnAlign | undefined): string | undefined {
  if (align === "right") return "text-right";
  if (align === "center") return "text-center";
  return undefined;
}

export type DataTableV2Props<T> = {
  schema: TableSchema<T>;
  data: T[];
  getRowId: (row: T) => string;
  initialSort?: SortingState;
  emptyMessage?: string;
  className?: string;
  pageSize?: number;
  onRowClick?: (row: T) => void;
  /**
   * Render shimmer skeleton rows instead of the empty message while the first
   * query is still resolving, so unresolved `data` doesn't read as "no data".
   */
  isLoading?: boolean;
};

/**
 * Schema-driven data table. Generates TanStack Table columns + toolbar from a
 * `TableSchema<T>`. State is component-local on purpose: the previous
 * nuqs-backed URL state locked the renderer for 30s+ on the first router
 * navigation after a cold page load (nuqs's TanStack Router adapter is
 * experimental and livelocks against in-flight route transitions). Shareable
 * filter URLs can return later via the router's native search params.
 */
export function DataTableV2<T>({
  schema,
  data,
  getRowId,
  initialSort,
  emptyMessage = "No results.",
  className,
  pageSize = 25,
  onRowClick,
  isLoading = false,
}: DataTableV2Props<T>) {
  const columns = React.useMemo(() => toColumnDefs<T>(schema), [schema]);
  const searchKeys = React.useMemo(() => searchableIds(schema), [schema]);
  const filters = React.useMemo(() => filterDescriptors(schema), [schema]);

  const [sorting, setSorting] = React.useState<SortingState>(initialSort ?? []);
  const [globalFilter, setGlobalFilter] = React.useState("");
  const [pageIndex, setPageIndex] = React.useState(0);
  const [columnFilters, setLocalFilters] = React.useState<ColumnFiltersState>([]);

  const setColumnFilter = (id: string, value: string[] | undefined) => {
    setLocalFilters((prev) => {
      const next = prev.filter((p) => p.id !== id);
      if (value && value.length > 0) next.push({ id, value });
      return next;
    });
  };

  const table = useReactTable({
    data,
    columns,
    state: {
      sorting,
      columnFilters,
      globalFilter,
      pagination: { pageIndex, pageSize },
    },
    onSortingChange: setSorting,
    onPaginationChange: (updater) => {
      const next = typeof updater === "function" ? updater({ pageIndex, pageSize }) : updater;
      setPageIndex(next.pageIndex);
    },
    getRowId: (row) => getRowId(row),
    getCoreRowModel: getCoreRowModel(),
    getSortedRowModel: getSortedRowModel(),
    getFilteredRowModel: getFilteredRowModel(),
    getPaginationRowModel: getPaginationRowModel(),
    getFacetedRowModel: getFacetedRowModel(),
    getFacetedUniqueValues: getFacetedUniqueValues(),
    getFacetedMinMaxValues: getFacetedMinMaxValues(),
    globalFilterFn: (row, _columnId, value) => {
      if (searchKeys.length === 0) return true;
      const needle = String(value ?? "").toLowerCase();
      if (!needle) return true;
      return searchKeys.some((k) => {
        const cell = (row.original as Record<string, unknown>)[k];
        return String(cell ?? "")
          .toLowerCase()
          .includes(needle);
      });
    },
    filterFns: {},
  });

  const anyFilter = columnFilters.length > 0 || globalFilter.length > 0;
  const resetFilters = () => {
    setGlobalFilter("");
    setLocalFilters([]);
  };

  return (
    <div className={cn("flex flex-col gap-3", className)}>
      <Toolbar
        table={table}
        filters={filters}
        columnFilters={columnFilters}
        searchKeys={searchKeys}
        globalFilter={globalFilter}
        onGlobalFilterChange={setGlobalFilter}
        onColumnFilterChange={setColumnFilter}
        onReset={resetFilters}
        anyFilter={anyFilter}
        rowCount={table.getFilteredRowModel().rows.length}
        totalCount={data.length}
      />

      <div className="overflow-hidden rounded-[var(--radius-bubble-md,22px)] border border-[var(--glass-edge)]">
        <Table>
          <TableHeader>
            {table.getHeaderGroups().map((hg) => (
              <TableRow key={hg.id}>
                {hg.headers.map((h) => {
                  const sortDir = h.column.getIsSorted();
                  const canSort = h.column.getCanSort();
                  const meta = h.column.columnDef.meta as ColumnMeta | undefined;
                  return (
                    <TableHead
                      key={h.id}
                      className={alignClass(meta?.align)}
                      style={
                        h.column.columnDef.size ? { width: h.column.columnDef.size } : undefined
                      }
                    >
                      {h.isPlaceholder ? null : canSort ? (
                        <button
                          type="button"
                          onClick={h.column.getToggleSortingHandler()}
                          className={cn(
                            "inline-flex items-center gap-1 hover:text-foreground",
                            meta?.align === "right" && "flex-row-reverse",
                            meta?.align === "center" && "justify-center",
                          )}
                        >
                          {flexRender(h.column.columnDef.header, h.getContext())}
                          {sortDir === "asc" ? (
                            <ArrowUp className="size-3" />
                          ) : sortDir === "desc" ? (
                            <ArrowDown className="size-3" />
                          ) : (
                            <ChevronsUpDown className="size-3 opacity-40" />
                          )}
                        </button>
                      ) : (
                        flexRender(h.column.columnDef.header, h.getContext())
                      )}
                    </TableHead>
                  );
                })}
              </TableRow>
            ))}
          </TableHeader>
          <TableBody>
            {isLoading ? (
              <TableRow>
                <TableCell colSpan={columns.length} className="p-0">
                  <SkeletonRows count={Math.min(pageSize, 8)} rowHeight={40} />
                </TableCell>
              </TableRow>
            ) : table.getRowModel().rows.length === 0 ? (
              <TableRow>
                <TableCell colSpan={columns.length} className="p-0">
                  <TableEmptyState message={emptyMessage} />
                </TableCell>
              </TableRow>
            ) : (
              table.getRowModel().rows.map((row) => (
                <TableRow
                  key={row.id}
                  className={onRowClick ? "cursor-pointer" : undefined}
                  onClick={onRowClick ? () => onRowClick(row.original) : undefined}
                >
                  {row.getVisibleCells().map((cell) => {
                    const meta = cell.column.columnDef.meta as ColumnMeta | undefined;
                    return (
                      <TableCell
                        key={cell.id}
                        className={cn(alignClass(meta?.align), meta?.className)}
                      >
                        {flexRender(cell.column.columnDef.cell, cell.getContext())}
                      </TableCell>
                    );
                  })}
                </TableRow>
              ))
            )}
          </TableBody>
        </Table>
      </div>

      <div className="flex items-center justify-between text-xs text-muted-foreground">
        <span>
          Page {pageIndex + 1} of {table.getPageCount() || 1}
        </span>
        <div className="flex gap-1">
          <Button
            variant="outline"
            size="sm"
            onClick={() => setPageIndex(Math.max(0, pageIndex - 1))}
            disabled={pageIndex === 0}
            className="h-7"
          >
            Prev
          </Button>
          <Button
            variant="outline"
            size="sm"
            onClick={() => setPageIndex(pageIndex + 1)}
            disabled={pageIndex + 1 >= (table.getPageCount() || 1)}
            className="h-7"
          >
            Next
          </Button>
        </div>
      </div>
    </div>
  );
}

/** Faceted counts per option, honoring every OTHER active filter (TanStack's
 *  faceted row model excludes the column's own filter), bucketed via toValue. */
function facetCounts<T>(
  column: Column<T, unknown> | undefined,
  toValue: ((raw: unknown) => string | undefined) | undefined,
): Map<string, number> {
  const counts = new Map<string, number>();
  if (!column) return counts;
  for (const row of column.getFacetedRowModel().rows) {
    const raw = row.getValue(column.id);
    const key = toValue ? toValue(raw) : raw == null ? undefined : String(raw);
    if (key === undefined) continue;
    counts.set(key, (counts.get(key) ?? 0) + 1);
  }
  return counts;
}

function Toolbar<T>({
  table,
  filters,
  columnFilters,
  searchKeys,
  globalFilter,
  onGlobalFilterChange,
  onColumnFilterChange,
  onReset,
  anyFilter,
  rowCount,
  totalCount,
}: {
  table: TanstackTable<T>;
  filters: ColumnDescriptor<T, unknown>[];
  columnFilters: ColumnFiltersState;
  searchKeys: string[];
  globalFilter: string;
  onGlobalFilterChange: (v: string) => void;
  onColumnFilterChange: (id: string, value: string[] | undefined) => void;
  onReset: () => void;
  anyFilter: boolean;
  rowCount: number;
  totalCount: number;
}) {
  if (filters.length === 0 && searchKeys.length === 0) {
    return null;
  }
  const activeFor = (id: string): string[] =>
    (columnFilters.find((f) => f.id === id)?.value as string[]) ?? [];

  return (
    <div className="flex flex-wrap items-center gap-2">
      {searchKeys.length > 0 && (
        <Input
          value={globalFilter}
          onChange={(e) => onGlobalFilterChange(e.target.value)}
          placeholder="Search…"
          className="h-8 w-64"
        />
      )}
      {filters.map((field) => {
        const filter = field.filter;
        if (filter?.kind === "checkbox") {
          const selected = new Set(activeFor(field.id));
          const counts = facetCounts(table.getColumn(field.id), filter.toValue);
          return (
            <div key={field.id} className="flex flex-wrap items-center gap-1">
              <span className="text-xs text-muted-foreground">{field.header}:</span>
              {filter.options.map((opt) => {
                const on = selected.has(opt.value);
                const count = counts.get(opt.value) ?? 0;
                return (
                  <Badge
                    key={opt.value}
                    variant={on ? "default" : "outline"}
                    className="cursor-pointer select-none gap-1"
                    onClick={() => {
                      const next = new Set(selected);
                      if (on) next.delete(opt.value);
                      else next.add(opt.value);
                      onColumnFilterChange(field.id, next.size > 0 ? Array.from(next) : undefined);
                    }}
                  >
                    {opt.label}
                    <span className="tabular-nums opacity-60">{count}</span>
                  </Badge>
                );
              })}
            </div>
          );
        }
        if (filter?.kind === "slider") {
          return (
            <SliderFilter
              key={field.id}
              label={field.header}
              filter={filter}
              column={table.getColumn(field.id)}
              value={activeFor(field.id)}
              onChange={(range) => onColumnFilterChange(field.id, range)}
            />
          );
        }
        if (filter?.kind === "input") {
          const v = activeFor(field.id)[0] ?? "";
          return (
            <Input
              key={field.id}
              value={v}
              placeholder={filter.placeholder ?? String(field.header)}
              onChange={(e) =>
                onColumnFilterChange(field.id, e.target.value ? [e.target.value] : undefined)
              }
              className="h-8 w-40"
            />
          );
        }
        return null;
      })}
      {anyFilter && (
        <Button variant="ghost" size="sm" onClick={onReset} className="h-8">
          Reset
          <X className="ml-1 size-3" />
        </Button>
      )}
      <div className="ml-auto text-xs text-muted-foreground">
        {rowCount} of {totalCount}
      </div>
    </div>
  );
}

/** Range filter: two-thumb slider bounded by the faceted min/max, with the
 *  selected window echoed in the label. Commits as `[min, max]` string pairs. */
function SliderFilter<T>({
  label,
  filter,
  column,
  value,
  onChange,
}: {
  label: React.ReactNode;
  filter: { kind: "slider"; min: number; max: number; step?: number; unit?: string };
  column: Column<T, unknown> | undefined;
  value: string[];
  onChange: (range: string[] | undefined) => void;
}) {
  const facetBounds = column?.getFacetedMinMaxValues();
  const lo = facetBounds?.[0] ?? filter.min;
  const hi = facetBounds?.[1] ?? filter.max;
  const active = value.length === 2 ? [Number(value[0]), Number(value[1])] : null;
  const current = active ?? [lo, hi];

  return (
    <div className="flex items-center gap-2">
      <span className="whitespace-nowrap text-xs text-muted-foreground">
        {label}: {Math.round(current[0]!).toLocaleString()}–
        {Math.round(current[1]!).toLocaleString()}
        {filter.unit ? ` ${filter.unit}` : ""}
      </span>
      <Slider
        className="w-36"
        min={lo}
        max={hi}
        step={filter.step ?? 1}
        value={[current[0]!, current[1]!]}
        onValueChange={(next) => {
          // Snapping back to the full range clears the filter.
          if (next[0]! <= lo && next[1]! >= hi) onChange(undefined);
          else onChange([String(next[0]), String(next[1])]);
        }}
      />
    </div>
  );
}

import type { ColumnDef, FilterFn } from "@tanstack/react-table";

import type { ColumnAlign, ColumnDescriptor, ColumnFilter, TableSchema } from "./types";

/**
 * Build the TanStack `filterFn` for a schema filter. URL state stores every
 * filter value as `string[]`, so each fn parses that shape:
 *  - checkbox → OR-match the (optionally bucketed) cell value against selected
 *  - slider   → numeric range [min, max]
 *  - input    → case-insensitive substring
 */
function filterFnFor<T>(filter: ColumnFilter): FilterFn<T> {
  if (filter.kind === "checkbox") {
    const toValue = filter.toValue ?? ((raw: unknown) => (raw == null ? undefined : String(raw)));
    return (row, columnId, value) => {
      const selected = value as string[] | undefined;
      if (!selected || selected.length === 0) return true;
      const mapped = toValue(row.getValue(columnId));
      return mapped !== undefined && selected.includes(mapped);
    };
  }
  if (filter.kind === "slider") {
    return (row, columnId, value) => {
      const range = (value as Array<string | number> | undefined)?.map(Number);
      if (!range || range.length < 2) return true;
      const min = range[0] ?? Number.NEGATIVE_INFINITY;
      const max = range[1] ?? Number.POSITIVE_INFINITY;
      const n = Number(row.getValue(columnId));
      if (Number.isNaN(n)) return false;
      return (Number.isNaN(min) || n >= min) && (Number.isNaN(max) || n <= max);
    };
  }
  // input
  return (row, columnId, value) => {
    const needle = String((value as string[] | undefined)?.[0] ?? "").toLowerCase();
    if (!needle) return true;
    return String(row.getValue(columnId) ?? "")
      .toLowerCase()
      .includes(needle);
  };
}

/**
 * Per-column presentation hints stashed on the TanStack `ColumnDef.meta` so the
 * table renderer can read the schema's `align` + `className` when emitting the
 * header/body cells — making alignment a single source of truth instead of
 * being duplicated in inner spans.
 */
export type ColumnMeta = {
  align?: ColumnAlign;
  className?: string;
};

/**
 * Convert a schema array into TanStack Table `ColumnDef[]`. Preserves order
 * and resolves the default accessor (row[id]) when none is provided.
 */
export function toColumnDefs<T>(schema: TableSchema<T>): ColumnDef<T, unknown>[] {
  return schema.map((col) => toColumnDef<T>(col));
}

function toColumnDef<T>(col: ColumnDescriptor<T, unknown>): ColumnDef<T, unknown> {
  const accessor = col.accessor ?? ((row: T) => (row as Record<string, unknown>)[col.id]);
  return {
    id: col.id,
    accessorFn: (row) => accessor(row),
    header: () => col.header,
    cell: ({ row, getValue }) => col.render(getValue(), row.original),
    enableSorting: col.sortable ?? false,
    enableColumnFilter: !!col.filter,
    filterFn: col.filter ? filterFnFor<T>(col.filter) : undefined,
    size: col.size,
    meta: { align: col.align, className: col.className } satisfies ColumnMeta,
  };
}

/**
 * Pluck the column ids that should participate in the global search input.
 */
export function searchableIds<T>(schema: TableSchema<T>): string[] {
  return schema.filter((c) => c.searchable).map((c) => c.id);
}

/**
 * Pluck the columns that have a filter descriptor attached. The order is
 * preserved so toolbar layout matches the schema order.
 */
export function filterDescriptors<T>(schema: TableSchema<T>): ColumnDescriptor<T, unknown>[] {
  return schema.filter((c) => !!c.filter);
}

import * as React from "react";
import { ArrowDownRight, ArrowUpRight, type LucideIcon } from "lucide-react";

import { Badge } from "@/components/ui/badge";
import { cn } from "@/lib/utils";

import type { ColumnDescriptor } from "./types";
import { EmptyCell } from "./table-primitives";

/**
 * A source as far as this table is concerned: a value, how to name it, and how
 * to tint its badge. The dictionary itself lives with the domain (moneytrees
 * owns `convex/lib/sources.ts`) so this package stays app-agnostic, matching
 * its existing stance on staying router-agnostic.
 */
export type SourceOption = {
  value: string;
  /** Compact name for the badge. */
  label: string;
  /** Full name for the filter dropdown. Falls back to `label`. */
  filterLabel?: string;
  /** Tailwind classes for the badge tint. */
  tint: string;
};

// ── createSourceColumn ───────────────────────────────────────────────────────

export function createSourceColumn<T>(opts: {
  id?: string;
  label?: string;
  size?: number;
  accessor?: (row: T) => string;
  /** The sources this column can render and filter by. */
  sources: readonly SourceOption[];
}): ColumnDescriptor<T, string> {
  const accessor =
    opts.accessor ?? ((row: T) => (row as Record<string, unknown>)["source"] as string);
  const bySource = new Map(opts.sources.map((s) => [s.value, s]));
  return {
    id: opts.id ?? "source",
    header: opts.label ?? "Src",
    size: opts.size ?? 72,
    accessor,
    render: (value) => {
      // An unknown source still renders readably rather than blank, so a newly
      // ingested source is visibly wrong instead of invisibly missing.
      const info = bySource.get(value) ?? {
        value,
        label: value,
        tint: "bg-muted text-muted-foreground",
      };
      return (
        <Badge variant="outline" className={cn("text-2xs", info.tint)}>
          {info.label}
        </Badge>
      );
    },
    filter: {
      kind: "checkbox",
      options: opts.sources.map((s) => ({
        value: s.value,
        label: s.filterLabel ?? s.label,
      })),
    },
  };
}

// ── createTickerColumn ───────────────────────────────────────────────────────

export function createTickerColumn<T>(opts: {
  id?: string;
  label?: string;
  size?: number;
  accessor?: (row: T) => string;
  searchable?: boolean;
}): ColumnDescriptor<T, string> {
  return {
    id: opts.id ?? "symbol",
    header: opts.label ?? "Ticker",
    size: opts.size ?? 100,
    accessor: opts.accessor ?? ((row) => (row as Record<string, unknown>)["symbol"] as string),
    searchable: opts.searchable ?? true,
    sortable: true,
    render: (value) => <span className="font-mono text-xs font-semibold">${value}</span>,
  };
}

// ── createTickerListColumn ───────────────────────────────────────────────────
// Renders an array of related-ticker strings as bubbly pill chips.

export function createTickerListColumn<T>(opts: {
  id?: string;
  label?: string;
  size?: number;
  accessor?: (row: T) => string[];
  max?: number;
  /**
   * When provided, pills render as buttons that call back with the symbol —
   * the consuming app decides what navigation means (this package stays
   * router-agnostic).
   */
  onTickerClick?: (symbol: string) => void;
}): ColumnDescriptor<T, string[]> {
  return {
    id: opts.id ?? "relatedTickers",
    header: opts.label ?? "Tickers",
    size: opts.size ?? 160,
    accessor:
      opts.accessor ?? ((row) => (row as Record<string, unknown>)["relatedTickers"] as string[]),
    render: (values) => {
      const max = opts.max ?? 3;
      const list = (values ?? []).slice(0, max);
      const overflow = (values?.length ?? 0) - list.length;
      const pillClass = "rounded-full bg-primary/10 px-2 py-0.5 text-2xs font-mono text-primary";
      return (
        <div className="flex flex-wrap gap-1">
          {list.map((t) =>
            opts.onTickerClick ? (
              <button
                key={t}
                type="button"
                className={cn(pillClass, "hover:bg-primary/20")}
                onClick={(e) => {
                  e.stopPropagation();
                  opts.onTickerClick!(t);
                }}
              >
                ${t}
              </button>
            ) : (
              <span key={t} className={pillClass}>
                ${t}
              </span>
            ),
          )}
          {overflow > 0 && <span className="text-2xs text-muted-foreground">+{overflow}</span>}
        </div>
      );
    },
  };
}

// ── createSentimentColumn ────────────────────────────────────────────────────

type Sentiment = "bullish" | "neutral" | "bearish" | undefined;

function classifySentiment(value: number | undefined): Sentiment {
  if (value === undefined || value === null) return undefined;
  if (value > 0) return "bullish";
  if (value < 0) return "bearish";
  return "neutral";
}

export function createSentimentColumn<T>(opts: {
  id?: string;
  label?: string;
  size?: number;
  /** Accessor returns the raw -1..1 sentiment score; we classify it here. */
  accessor?: (row: T) => number | undefined;
}): ColumnDescriptor<T, number | undefined> {
  return {
    id: opts.id ?? "sentiment",
    header: opts.label ?? "Sentiment",
    size: opts.size ?? 110,
    accessor:
      opts.accessor ??
      ((row) => (row as Record<string, unknown>)["sentiment"] as number | undefined),
    sortable: true,
    filter: {
      kind: "checkbox",
      options: [
        { value: "bullish", label: "Bullish" },
        { value: "neutral", label: "Neutral" },
        { value: "bearish", label: "Bearish" },
      ],
      // Map the raw -1..1 score to its bucket so filtering + faceted counts
      // operate on Bullish/Neutral/Bearish rather than the numeric value.
      toValue: (raw) => classifySentiment(raw as number | undefined),
    },
    render: (value) => {
      const tone = classifySentiment(value);
      if (!tone) return <EmptyCell />;
      if (tone === "bullish") return <Badge variant="bull">Bullish</Badge>;
      if (tone === "bearish") return <Badge variant="bear">Bearish</Badge>;
      return <Badge variant="outline">Neutral</Badge>;
    },
  };
}

// ── createEngagementColumn ───────────────────────────────────────────────────

export function createEngagementColumn<T>(opts: {
  id?: string;
  label?: string;
  size?: number;
  accessor?: (row: T) => number;
  /** Attach a range slider filter (e.g. `{ min: 0, max: 5000 }`). */
  range?: { min: number; max: number; step?: number; unit?: string };
}): ColumnDescriptor<T, number> {
  return {
    id: opts.id ?? "engagementScore",
    header: opts.label ?? "Eng",
    size: opts.size ?? 80,
    // `align: "right"` is the single source of right-alignment — applied to
    // the cell wrapper by both table families. No per-factory `text-right`
    // className and no inner `text-right block` span.
    align: "right",
    sortable: true,
    className: "tabular-nums",
    accessor:
      opts.accessor ?? ((row) => (row as Record<string, unknown>)["engagementScore"] as number),
    filter: opts.range ? { kind: "slider", ...opts.range } : undefined,
    render: (value) => (
      <span className="font-mono text-xs tabular-nums">{(value ?? 0).toLocaleString()}</span>
    ),
  };
}

// ── createTimestampColumn ────────────────────────────────────────────────────

function relativeTime(ms: number): string {
  const seconds = Math.round((Date.now() - ms) / 1000);
  if (seconds < 5) return "just now";
  if (seconds < 60) return `${seconds}s ago`;
  const minutes = Math.round(seconds / 60);
  if (minutes < 60) return `${minutes}m ago`;
  const hours = Math.round(minutes / 60);
  if (hours < 24) return `${hours}h ago`;
  const days = Math.round(hours / 24);
  if (days < 7) return `${days}d ago`;
  const weeks = Math.round(days / 7);
  if (weeks < 5) return `${weeks}w ago`;
  return new Date(ms).toLocaleDateString();
}

export function createTimestampColumn<T>(opts: {
  id?: string;
  label?: string;
  size?: number;
  accessor?: (row: T) => number;
}): ColumnDescriptor<T, number> {
  return {
    id: opts.id ?? "ingestedAt",
    header: opts.label ?? "When",
    size: opts.size ?? 96,
    sortable: true,
    accessor: opts.accessor ?? ((row) => (row as Record<string, unknown>)["ingestedAt"] as number),
    render: (value) => (
      <time
        dateTime={new Date(value).toISOString()}
        title={new Date(value).toLocaleString()}
        className="text-xs text-muted-foreground"
      >
        {relativeTime(value)}
      </time>
    ),
  };
}

// ── createPriceChangeColumn ─────────────────────────────────────────────────

export function createPriceChangeColumn<T>(opts: {
  id?: string;
  label?: string;
  size?: number;
  accessor?: (row: T) => number | undefined;
}): ColumnDescriptor<T, number | undefined> {
  return {
    id: opts.id ?? "priceChange24h",
    header: opts.label ?? "24h",
    size: opts.size ?? 96,
    align: "right",
    sortable: true,
    accessor:
      opts.accessor ??
      ((row) => (row as Record<string, unknown>)["priceChange24h"] as number | undefined),
    render: (value) => {
      if (value === undefined || value === null) {
        return <EmptyCell />;
      }
      const Icon: LucideIcon = value >= 0 ? ArrowUpRight : ArrowDownRight;
      const tone = value >= 0 ? "text-[var(--color-bull-fg)]" : "text-[var(--color-bear-fg)]";
      return (
        <span className={cn("inline-flex items-center gap-1 font-mono text-xs tabular-nums", tone)}>
          <Icon className="size-3" />
          {value >= 0 ? "+" : ""}
          {(value * 100).toFixed(2)}%
        </span>
      );
    },
  };
}

// ── createTextColumn (generic catch-all, useful for trend `content`) ────────

export function createTextColumn<T>(opts: {
  id: string;
  label: React.ReactNode;
  size?: number;
  searchable?: boolean;
  accessor?: (row: T) => string;
  render?: (value: string, row: T) => React.ReactNode;
}): ColumnDescriptor<T, string> {
  return {
    id: opts.id,
    header: opts.label,
    size: opts.size,
    searchable: opts.searchable ?? true,
    accessor: opts.accessor ?? ((row) => (row as Record<string, unknown>)[opts.id] as string),
    render:
      opts.render ??
      ((value) => (
        <span className="block truncate text-sm" title={value}>
          {value}
        </span>
      )),
  };
}

