/**
 * Shared table primitives for the schema-driven table family (`<DataTableV2>`
 * + `<LiveFeedTable>`). Centralised here so the em-dash placeholder, empty
 * state, and loading skeletons read identically across both tables instead of
 * being re-implemented inline per column / per table.
 */

/**
 * Em-dash placeholder for a null/undefined cell value. Used by every nullable
 * cell renderer (sentiment, priceChange, …) so the "no value" affordance is
 * one piece of markup rather than a per-column inline span.
 */
export function EmptyCell({ className }: { className?: string }) {
  return (
    <span className={cn("text-xs text-muted-foreground", className)} aria-hidden>
      —
    </span>
  );
}

/**
 * Unified empty-state row body. Both tables render this when there is data but
 * the (filtered) result set is empty, so the height + muted styling align.
 */
export function TableEmptyState({ message }: { message: string }) {
  return (
    <div className="flex h-24 items-center justify-center text-sm text-muted-foreground">
      {message}
    </div>
  );
}

/**
 * N shimmer rows shown while the first query is still resolving (data is
 * `undefined`). Reuses the same `animate-pulse` + bubble-radius token as the
 * dashboard ticker skeletons so loading reads as "loading", not "no data".
 */
export function SkeletonRows({ count, rowHeight }: { count: number; rowHeight: number }) {
  return (
    <div className="space-y-1 p-2">
      {Array.from({ length: count }).map((_, i) => (
        <div
          key={i}
          className="animate-pulse rounded-bubble-sm bg-[var(--glass-tint-card)]"
          style={{ height: rowHeight }}
        />
      ))}
    </div>
  );
}

import type { ReactNode } from "react";

/**
 * Schema-driven column descriptor — inspired by the openstatus data-table
 * pattern (https://data-table.openstatus.dev/docs/table-schema), adapted for
 * moneytrees's Vite + TanStack Router stack.
 *
 * One descriptor describes the column's identity, how to extract its value
 * from a row, how to render the cell, optional sorting/filter behaviour, and
 * presentation hints. The schema is consumed by `<DataTableV2>` to produce
 * TanStack Table `ColumnDef[]`, the filter sidebar fields, and the set of
 * keys to include in the global search.
 */
export type ColumnAlign = "left" | "right" | "center";

export type ColumnFilter =
  | {
      kind: "checkbox";
      options: ReadonlyArray<{ label: string; value: string }>;
      /**
       * Map a raw cell value to the option `value` it belongs to, for columns
       * whose stored value differs from the bucket the user filters on (e.g. a
       * -1..1 sentiment score → "bullish"). Used for both filtering and faceted
       * counts. Defaults to `String(raw)`.
       */
      toValue?: (raw: unknown) => string | undefined;
    }
  | { kind: "input"; placeholder?: string }
  | { kind: "slider"; min: number; max: number; step?: number; unit?: string };

export type ColumnDescriptor<T, V = unknown> = {
  /** Stable identifier (used as the TanStack column id and URL-state key). */
  id: string;
  /** Header cell content. */
  header: ReactNode;
  /** Cell value extractor. Defaults to `(row) => row[id]`. */
  accessor?: (row: T) => V;
  /** Cell renderer. Receives the extracted value + the full row. */
  render: (value: V, row: T) => ReactNode;
  /** Fixed pixel width hint. */
  size?: number;
  /** Whether the header is sortable. */
  sortable?: boolean;
  /** Whether the value participates in global search. */
  searchable?: boolean;
  /** Optional filter widget for the toolbar. */
  filter?: ColumnFilter;
  /** Cell + header horizontal alignment. Defaults to `"left"`. */
  align?: ColumnAlign;
  /** Extra Tailwind classes applied to the cell wrapper. */
  className?: string;
};

// `any` is intentional: per-column V varies across the schema, and TypeScript
// array generics are invariant — using `unknown` here would reject perfectly
// typed factory output like `ColumnDescriptor<T, string>`. This mirrors the
// same trade-off TanStack Table makes with `ColumnDef<T, any>[]`. Consumers
// still see the column-specific value type inside each `render(value, row)`
// callback because the factories preserve their own V.
// eslint-disable-next-line @typescript-eslint/no-explicit-any
export type TableSchema<T> = ReadonlyArray<ColumnDescriptor<T, any>>;
